import{z as A,x as p,o as E,c as B,q as r,j as s,D as e,d as i,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Spark 与 DAG","description":"","frontmatter":{"title":"Spark 与 DAG","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spark-dag.md","filePath":"cs/spark-dag.md","lastUpdated":1791413859000}'),n={name:"cs/spark-dag.md"};function D(d,a,h,c,f,m){const t=p("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="spark-与-dag" tabindex="-1">Spark 与 DAG <a class="header-anchor" href="#spark-与-dag" aria-label="Permalink to &quot;Spark 与 DAG&quot;">​</a></h1><div class="epigraph"><p>把作业收成 RDD/DataFrame 上的有向无环图，窄依赖流水线，宽依赖才洗牌；谱系让失败后从检查点重算，而不必每两跳落盘。</p><footer>—— Zaharia et al., Resilient Distributed Datasets, NSDI 2012；Spark SQL / Catalyst</footer></div><p><a href="/cs/mapreduce">上一课</a>强制 map→shuffle→reduce。缺口是多阶段查询：过滤、map、join、再聚合。本课钉 Spark 式 DAG；流窗口下一课把无界数据接进来。不重写 MR 的再执行定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MR 每次 shuffle 物化，迭代与交互查询太慢。RDD：不可变分区集合 + 转换谱系。宽依赖（groupBy、join）画成 DAG 的边，窄依赖（map、filter）融合。缺口是<strong>计划与谱系</strong>：Catalyst 把 SQL 收成同一 DAG，失败按谱系重算丢失分区。与湖仓：DataFrame 读表快照，写回表格式提交。</p><p><span class="marginnote">直觉类比：RDD 谱系像菜谱的「做法记录」而不是「做好的菜」。缓存是把菜放进冰箱；冰箱丢了没关系，照着记录把丢的那一盘重做就行——前提是食材（上游输入分区）还能重新读到。</span></p><p><span class="marginnote">Zaharia, NSDI 2012。内存缓存是谱系上的提示，不是缓存一致性协议。倾斜仍在宽依赖上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读逻辑计划 → 优化（谓词下推、join 重排）→ 物理 DAG → 任务按分区调度。shuffle 服务替代 MR 的文件系统中间文件。AQE 运行时改 join 策略。与 TPC-H：后课基准测的就是这类 DAG。</p><p><span class="marginnote">术语翻译：窄依赖就是「一个父分区只喂一个子分区」，如 map、filter，能在同一任务里流水线跑完不落盘；宽依赖是「一个父分区要分给许多子分区」，如 groupBy、join，必须全局洗牌才能继续。DAG 上画的就是这条分界线。</span></p>',10)),(E(),s(o,null,{default:e(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQL%5B%22SQL%20%2F%20DataFrame%22%5D%20--%3E%20DAG%5B%22%E9%98%B6%E6%AE%B5%20DAG%22%5D%0A%20%20DAG%20--%3E%20N%5B%22%E7%AA%84%E4%BE%9D%E8%B5%96%E6%B5%81%E6%B0%B4%E7%BA%BF%22%5D%0A%20%20DAG%20--%3E%20W%5B%22%E5%AE%BD%E4%BE%9D%E8%B5%96%20shuffle%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>谱系是函数式重算：分区丢了，从最近检查点沿边再跑。需要确定性与可重读输入。宽依赖失败会重跑整个 shuffle 上游，比 MR 单任务再执行更贵也更灵活。Catalyst 做谓词下推与连接重排，物理层仍是 broadcast / sort-merge / hash——<a href="/cs/distributed-join-shuffle">分布式连接</a> 的同一菜单。整阶段代码生成对应 <a href="/cs/query-compilation">编译执行</a>。</p><p>调度：任务对分区。执行内存与存储缓存争用，扫描污染像 2Q。AQE 在运行时改 join 策略，是 <a href="/cs/adaptive-query-processing">自适应查询处理</a> 的集群实例。输出进湖仓表格式，提交快照即作业的「commit」。</p>',3)),(E(),s(o,null,{default:e(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOSE%5B%22%E6%9F%90%E5%88%86%E5%8C%BA%20Executor%20%E6%8C%82%E6%8E%89%22%5D%20--%3E%20TR%5B%22%E6%B2%BF%20RDD%20%E8%B0%B1%E7%B3%BB%E5%90%91%E4%B8%8A%E6%89%BE%E7%88%B6%E5%88%86%E5%8C%BA%22%5D%0A%20%20TR%20--%3E%20CK%7B%22%E4%B8%8A%E6%B8%B8%E6%9C%89%E7%BC%93%E5%AD%98%E6%88%96%E6%A3%80%E6%9F%A5%E7%82%B9%3F%22%7D%0A%20%20CK%20--%3E%7C%22%E6%9C%89%22%7C%20HIT%5B%22%E7%9B%B4%E6%8E%A5%E8%AF%BB%E7%BC%93%E5%AD%98%EF%BC%8C%E4%B8%8D%E5%86%8D%E9%87%8D%E7%AE%97%22%5D%0A%20%20CK%20--%3E%7C%22%E6%97%A0%22%7C%20RE%5B%22%E5%AF%B9%E7%88%B6%E5%88%86%E5%8C%BA%E9%87%8D%E8%B7%91%E7%AA%84%E4%BE%9D%E8%B5%96%E7%AE%97%E5%AD%90%22%5D%0A%20%20RE%20--%3E%20SHUF%7B%22%E8%B7%AF%E5%BE%84%E4%B8%8A%E8%B7%A8%E5%AE%BD%E4%BE%9D%E8%B5%96%3F%22%7D%0A%20%20SHUF%20--%3E%7C%22%E6%98%AF%22%7C%20REALL%5B%22%E9%87%8D%E8%B7%91%E6%95%B4%E4%B8%AA%20shuffle%20%E4%B8%8A%E6%B8%B8%22%5D%0A%20%20SHUF%20--%3E%7C%22%E5%90%A6%22%7C%20ONLY%5B%22%E5%8F%AA%E9%87%8D%E7%AE%97%E4%B8%A2%E7%9A%84%E9%82%A3%E4%B8%AA%E5%88%86%E5%8C%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>这张图回答的是：一个分区失败后重算的边界画在哪——窄依赖把重算限制在单个分区，宽依赖的边界才是重算的「断点」，缓存与检查点只是让断点上移的提示。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某发行版的调参表。下一课无界流：DAG 变成持续运行的图，窗口取代作业结束。不要把 Spark 当 OLTP：没有行锁热点路径，RTO 是作业级重跑。</p><p>后课默认：批分析用 DAG + 血统；shuffle 仍是税。流处理与窗口把无界输入切成可聚合的包。</p><p><span class="marginnote">常见误区：初学者容易以为容错靠备份副本。Spark 默认路线是不备份、按谱系重算，代价是重算时间而不是存储翻倍；只有重算特别贵（比如谱系很长）时才值得显式 checkpoint 把断点前移。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAG 把多阶段查询连成谱系；宽依赖才洗牌。</li><li>容错靠重算分区，前提是可重读与确定性。</li><li>流处理与窗口下一课。</li><li>出处：Zaharia et al., NSDI 2012；Catalyst。</li></ul>',7))])}const C=A(n,[["render",D]]);export{_ as __pageData,C as default};
